power = next((i['value'] for i in query_graph('SELECT ?value WHERE { <https://dbt-brick.link/brick/12345/dcp:Point_12345> ref:hasTimeseriesId ?series_ts_id . ?series_ts_id ref:hasExternalReference <https://dbt-brick.link/brick/12345/timeseries/12345> . <https://dbt-brick.link/brick/12345/dcp:ElectricPowerSensor_12345> ref:hasExternalReference <https://dbt-brick.link/brick/12345/timeseries/12346> . }') for i in query_graph('SELECT ?value WHERE { <https://dbt-brick.link/brick/12345/timeseries/12346> ref:hasValue ( ?timestamp, ?value ) . FILTER ( ?timestamp = "2018-04-02T00:00:00" && ?value > 0) }'))['value'] if power > 0 else 0)
# Query the hourly values of the lighting sensor at 2018-04-02
light_values = query_graph('SELECT ?value WHERE { <https://dbt-brick.link/brick/12345/dcp:Point_12345> ref:hasTimeseriesId ?series_ts_id . ?series_ts_id ref:hasExternalReference <https://dbt-brick.link/brick/12345/timeseries/12345> . <https://dbt-brick.link/brick/12345/dcp:Point_12345> ref:hasValue (?timestamp, ?value) . FILTER ( ?timestamp = "2018-04-02" && ?value > 0 ) }
# The lighting energy = power * light_values
light_energy = [i['value']*float(power) for i in light_values][24]
print('{{"value": {}}}'.format(light_energy))"}}}
